styl:
.white-bg.b-exnova-text-99 {  background:#fff  }
.b-exnova-text-99 .nopoint {  cursor:default!important;display:block  }
.b-exnova-text-99 .black-title, .b-exnova-text-99 .title .red {  font-family:Helvetica!important  }
.b-exnova-text-99 .black-title {  color:#2a3554;font-size:36px;line-height:48px;font-weight:700  }
@media screen and (max-width:600px) {
  .b-exnova-text-99 .black-title {  font-size:30px!important;line-height:40px!important  }
}
.b-exnova-text-99 .black-sub, .b-exnova-text-99 .redish b, .b-exnova-text-99 .text, .b-exnova-text-99 .text a {  font-family:Helvetica!important  }
.b-exnova-text-99 .text {  font-size:16px;line-height:24px;color:#293455;font-weight:400  }
.b-exnova-text-99 .redish b, .b-exnova-text-99 .text a {  color:#213e8f;font-weight:700  }
.b-exnova-text-99 .block-head {  background:url(https://static.cdnpub.info/files/storage/public/5f/5a/1c0a7ff4f0j2e1f7e7/liner.png) right center no-repeat;background-size:100%  }
.b-exnova-text-99 .block-name, .b-exnova-text-99 .icon {  display:inline-block  }
.b-exnova-text-99 .block-name {  background:#fff;font-size:24px;line-height:29px;font-weight:700;color:#2a3554;font-family:Helvetica!important;vertical-align:middle;padding-right:15px  }
.b-exnova-text-99 .icon {  vertical-align:text-bottom;float:none;padding-right:11px  }
.b-exnova-text-99 .icon_1 {  max-width:27px  }
.b-exnova-text-99 .icon_2 {  max-width:24px;vertical-align:baseline  }
.b-exnova-text-99 .icon_3 {  max-width:17px;vertical-align:bottom  }
.b-exnova-text-99 .icon_4, .b-exnova-text-99 .icon_5 {  max-width:27px;vertical-align:baseline  }
.b-exnova-text-99 .icon_5 {  max-width:24px  }
.b-exnova-text-99 .item-text, .b-exnova-text-99 .red-link {  color:#697189;font-size:14px;line-height:21px;font-weight:400;font-family:Helvetica!important  }
.b-exnova-text-99 .red-link {  color:#ff2c2f;line-height:17px;font-weight:700;letter-spacing:1px;margin-bottom:30px;float:none;display:block  }
.b-exnova-text-99 .arr {  display:inline-block;float:none;vertical-align:middle;max-width:6px;padding-right:6px;padding-bottom:2px  }
.b-exnova-text-99 .pb15 {  padding-bottom:15px  }
.b-exnova-text-99 .pt15 {  padding-top:15px  }
.b-exnova-text-99 .mtb20 {  margin-top:20px;margin-bottom:20px  }
